#include <condition_variable>
#include <mutex>
#include <thread>

void run() {
  std::mutex m;
  std::condition_variable cv;
  bool done = false;
  std::thread([&] {
    {
      std::lock_guard lk(m);
      done = true;
    }
    cv.notify_one();
  }).detach();
  std::unique_lock lk(m);
  cv.wait(lk, [&] { return done; });
}

